const items = $input.all();
const results = [];
items.forEach((it, idx) => {
  const batch = $('Get Active Batches').itemMatching(idx).json;
  const r = it.json;

  const startDate = new Date(batch.start_date);
  const hoursSinceStart = (Date.now() - startDate.getTime()) / 3600000;

  // คำนวณ gravity velocity เอง (SG/วัน) จาก gravity_sg ที่เราแปลงหน่วยและยืนยัน
  // ถูกต้องแล้วในระบบเอง แทนการเชื่อ field gravityVelocity ดิบจาก RAPT ตรงๆ
  // เพราะ unit ของมันไม่ยืนยันชัด วิธีนี้แม่นยำกว่าและตรวจสอบย้อนกลับได้
  let gravityVelocity = null;
  let velocityWindowHours = null;
  if (r.gravity_sg != null && r.gravity_sg_24h_ago != null && r.pill_time_utc && r.pill_time_utc_24h_ago) {
    const hoursSpan = (new Date(r.pill_time_utc) - new Date(r.pill_time_utc_24h_ago)) / 3600000;
    if (hoursSpan > 0) {
      gravityVelocity = (r.gravity_sg - r.gravity_sg_24h_ago) / (hoursSpan / 24);
      velocityWindowHours = hoursSpan;
    }
  }

  const tempDiff = (r.pill_temp_c != null && r.controller_temp_c != null)
    ? (r.pill_temp_c - r.controller_temp_c)
    : null;

  // apparent attenuation % จาก OG จริงที่ Pill วัดได้ตอนเริ่ม batch เทียบกับปัจจุบัน
  // เป็นตัวชี้วัดหลักที่ BJCP ใช้บอกว่าใกล้จบการหมักแค่ไหน (ทั่วไปจบที่ 65-80%)
  // เชื่อถือได้เฉพาะตอนที่ reading แรกอยู่ใกล้ start_date จริง (ไม่เกิน 24 ชม.) —
  // ถ้าเครื่องเพิ่งเริ่มเก็บข้อมูลหลัง batch เริ่มไปแล้วหลายวัน ค่าที่ได้จะไม่ใช่ OG
  // จริง แต่เป็น gravity ที่หมักไปแล้วบางส่วน ทำให้ attenuation% ต่ำกว่าความจริงมาก
  // ต้องบอก AI ตรงๆ ว่าค่านี้เชื่อถือได้แค่ไหน ไม่งั้น AI จะเชื่อเลขที่ผิดมากกว่า
  // เวลาที่ผ่านไปจริง (เคยเกิดขึ้นจริง: 139 ชม.เข้า batch แต่ attenuation อ่านได้
  // ใกล้ 0% เพราะ OG proxy มาจาก reading ที่เพิ่งเริ่มเก็บ ทำให้ AI ตอบ lag ผิด)
  let apparentAttenuationPercent = null;
  let ogReliable = false;
  if (r.gravity_sg != null && r.gravity_sg_og != null && r.gravity_sg_og > 1 && r.pill_time_utc_og) {
    const ogDelayHours = (new Date(r.pill_time_utc_og) - startDate) / 3600000;
    ogReliable = ogDelayHours <= 24;
    apparentAttenuationPercent = ((r.gravity_sg_og - r.gravity_sg) / (r.gravity_sg_og - 1)) * 100;
  }

  const promptText = `คุณคือผู้เชี่ยวชาญการหมักเบียร์ (อ้างอิงหลักการจาก BJCP Yeast & Fermentation guide, John Palmer "How to Brew", Brew Your Own Fermentation Timeline) วิเคราะห์ว่า batch นี้อยู่เฟสไหนใน 6 เฟสนี้ โดยพิจารณาทุกตัวแปรประกอบกัน

สำคัญ: ถ้าตัวชี้วัดขัดแย้งกัน ให้เชื่อ "เวลาที่ผ่านไปจริงตั้งแต่เริ่ม batch" และ "ผลต่างอุณหภูมิ pill-ตู้ควบคุม" เป็นหลักก่อนเสมอ เพราะวัดตรงและเชื่อถือได้แน่นอน ส่วน apparent attenuation ให้ใช้เป็นข้อมูลเสริมเท่านั้น โดยเฉพาะถ้าข้อมูลระบุว่า OG ไม่น่าเชื่อถือ (ดูหมายเหตุในข้อมูล batch ด้านล่าง) ห้ามใช้ attenuation ที่ต่ำผิดปกติมาสรุปว่ายังอยู่เฟส lag ทั้งที่เวลาผ่านไปเกิน 24 ชม.และมีผลต่างอุณหภูมิที่บ่งชี้การหมักแล้ว

1. lag (0-24 ชม.แรกหลัง pitch): ยีสต์ปรับตัว ยังไม่มี krausen ชัดเจน, gravity แทบไม่ขยับ (apparent attenuation ~0%), แทบไม่มีผลต่างอุณหภูมิระหว่าง pill กับตู้ควบคุม (ยังไม่เกิดความร้อนจากปฏิกิริยา)

2. active_ferment (วันที่ 1-4, หนักสุดมักอยู่ใน 48-72 ชม.แรก): high krausen, gravity ลดเร็วที่สุดของทั้ง batch, ตาม BJCP ช่วงนี้มักลดไปแล้วราว 2/3-3/4 ของระยะทางถึง FG (apparent attenuation ไต่ขึ้นเร็วจนใกล้ 50-75%), ปฏิกิริยาคายความร้อน (exothermic) ทำให้ pill มักอุ่นกว่าตู้ควบคุม 2-5°C — ถ้า pill temp สูงกว่าตู้ควบคุมชัดเจนคือสัญญาณเฟสนี้ที่ดี

3. slowing: krausen เริ่มยุบ, อัตราลด gravity ผ่อนลงจากจุดสูงสุดแต่ยัง "ลบชัดเจน" (ไม่ใช่ใกล้ 0), apparent attenuation มักอยู่แถวๆ 60-80% แล้วแต่ยังไม่นิ่ง, ผลต่างอุณหภูมิ pill-ตู้ควบคุมเริ่มแคบลงเพราะปฏิกิริยาน้อยลง

4. fg_stable: gravity velocity ใกล้ 0 ต่อเนื่อง (แนวทาง RAPT เองแนะนำให้ถือว่าหมักหลักเสร็จเมื่อ gravity velocity แตะ 0 แล้วเริ่ม cold crash ได้) ควรเห็นแนวโน้มนิ่งสัก 24-48 ชม.ถึงจะมั่นใจ, apparent attenuation ควรอยู่ในช่วงปกติของ BJCP คือ 65-80% (ต่ำ 65-70%, กลาง 71-75%, สูง 76-80%), ผลต่างอุณหภูมิ pill-ตู้ควบคุมควรใกล้ 0 ด้วย (ไม่มีความร้อนจากการหมักเหลือแล้ว)
   ⚠️ ข้อควรระวัง: ถ้า gravity velocity นิ่งแล้วแต่ apparent attenuation ต่ำกว่า ~60% หรือนิ่งเร็วผิดปกติ (เช่นภายใน 2-3 วันแรก) อาจเป็น "stuck fermentation" ไม่ใช่หมักเสร็จจริง ให้ระบุความสงสัยนี้ไว้ใน reasoning ด้วย (ไม่ต้องเปลี่ยน phase ที่ตอบ แค่เตือนไว้)

5. diacetyl_rest: ต้องผ่าน fg_stable มาก่อน แล้วมีการยกอุณหภูมิตู้ควบคุม (target_temperature) ขึ้นไปอยู่ช่วง 16-18°C ค้างไว้ 2-3 วัน (จำเป็นสำหรับ lager, แนะนำสำหรับ ale ส่วนใหญ่แม้ไม่บังคับ) — ดู target_temperature_c เทียบกับเฟสก่อนหน้าประกอบการตัดสิน

6. cold_crash: ต้องผ่าน fg_stable (และปกติ diacetyl_rest) มาก่อน แล้วมีการลดอุณหภูมิตู้ควบคุมลงเหลือ 0-4°C ค้างไว้ 1-3 วัน (ale ~1-2 วัน, lager ~2-3 วัน) เพื่อให้ยีสต์ตกตะกอน

ข้อมูล batch "${batch.beer_name || '(ไม่ระบุชื่อ)'}":
- เริ่มหมักมาแล้ว: ${hoursSinceStart.toFixed(1)} ชั่วโมง (${(hoursSinceStart / 24).toFixed(1)} วัน)
- เฟสล่าสุดที่บันทึกไว้: ${batch.current_phase}
- OG ที่ Pill วัดได้จริงตอนเริ่ม batch: ${r.gravity_sg_og ?? 'ไม่มีข้อมูล (ยังไม่มี reading ตั้งแต่ start_date)'} SG${r.gravity_sg_og != null ? (ogReliable ? ' (วัดใกล้ช่วงเริ่มหมักจริง เชื่อถือได้)' : ' (⚠️ วัดได้ช้ากว่า start_date เกิน 24 ชม. — ระบบเพิ่งเริ่มเก็บข้อมูล ค่านี้ไม่ใช่ OG จริง เป็นแค่ gravity ที่หมักไปแล้วบางส่วน ห้ามใช้เป็นหลักฐานหลัก)') : ''}
- gravity ปัจจุบัน: ${r.gravity_sg ?? 'ไม่มีข้อมูล'} SG
- apparent attenuation ถึงตอนนี้ (คำนวณจาก OG proxy ด้านบน เทียบเกณฑ์ BJCP 65-80%): ${apparentAttenuationPercent != null ? apparentAttenuationPercent.toFixed(1) + '%' + (ogReliable ? '' : ' (⚠️ ไม่น่าเชื่อถือ เพราะ OG proxy ไม่น่าเชื่อถือตามหมายเหตุด้านบน — อย่าใช้เลขนี้สรุปว่ายังอยู่เฟส lag)') : 'คำนวณไม่ได้'}
- gravity เมื่อ ~24 ชม.ก่อน: ${r.gravity_sg_24h_ago ?? 'ไม่มีข้อมูล (อาจยังไม่ผ่าน 24 ชม.แรกของการหมัก)'} SG
- gravity velocity ที่คำนวณจริงจากข้อมูล 2 จุดนี้: ${gravityVelocity != null ? gravityVelocity.toFixed(5) + ' SG/วัน (ช่วงเวลาที่ใช้คำนวณจริง ' + velocityWindowHours.toFixed(1) + ' ชม.)' : 'คำนวณไม่ได้ (ข้อมูลย้อนหลังไม่พอ)'}
- อุณหภูมิ Pill (วัดในของเหลวจริง): ${r.pill_temp_c ?? 'ไม่มีข้อมูล'}°C
- อุณหภูมิตู้ควบคุม: ${r.controller_temp_c ?? 'ไม่มีข้อมูล'}°C
- ผลต่างอุณหภูมิ (Pill - ตู้ควบคุม): ${tempDiff != null ? tempDiff.toFixed(2) + '°C' : 'คำนวณไม่ได้'}
- target temperature ที่ตู้ควบคุมตั้งไว้: ${r.target_temperature_c ?? 'ไม่มีข้อมูล'}°C

ตอบกลับเป็น JSON เท่านั้น ห้ามมีข้อความอื่นปนก่อน/หลัง รูปแบบ:
{"phase": "<lag|active_ferment|slowing|fg_stable|diacetyl_rest|cold_crash>", "reasoning": "<เหตุผลสั้นๆ ภาษาไทย อ้างอิงตัวเลขที่ให้มาประกอบ>"}`;

  results.push({
    json: {
      batch_id: batch.batch_id,
      beer_name: batch.beer_name,
      current_phase: batch.current_phase,
      gravity_sg: r.gravity_sg,
      temperature_c: r.pill_temp_c,
      gravity_velocity: gravityVelocity,
      prompt: promptText
    }
  });
});
return results;

const items = $input.all();
const results = [];
items.forEach((it, idx) => {
  const src = $('Build AI Prompt').itemMatching(idx).json;
  let phase = null, reasoning = null;
  try {
    const textBlock = (it.json.content || []).find(c => c.type === 'text');
    const text = textBlock ? textBlock.text : undefined;
    const parsed = JSON.parse(text);
    phase = parsed.phase;
    reasoning = parsed.reasoning;
  } catch (e) {
    phase = src.current_phase; // parse ไม่ได้ -> คงเฟสเดิมไว้ก่อน ไม่เปลี่ยนมั่ว
    reasoning = 'AI response parse error: ' + String(e);
  }
  results.push({
    json: {
      batch_id: src.batch_id,
      beer_name: src.beer_name,
      previous_phase: src.current_phase,
      detected_phase: phase,
      reasoning,
      gravity_sg: src.gravity_sg,
      temperature_c: src.temperature_c,
      gravity_velocity: src.gravity_velocity
    }
  });
});
return results;
